function ts_call(string $method,string $path,?array $payload=null,bool $bridge=false): array {$headers="Content-Type: application/json\r\n";if(!$bridge){$headers.="Cookie: ".getenv('TRAILWATCH_TEST_SESSION_COOKIE')."\r\nX-CSRF-Token: ".getenv('TRAILWATCH_TEST_CSRF_TOKEN')."\r\n";}else $headers.="X-Bridge-Token: ".($GLOBALS['token']??'')."\r\n";$ctx=stream_context_create(['http'=>['method'=>$method,'header'=>$headers,'content'=>$payload===null?'':json_encode($payload,JSON_THROW_ON_ERROR),'ignore_errors'=>true,'timeout'=>8]]);$raw=@file_get_contents($GLOBALS['base'].$path,false,$ctx);$status=(int)substr($http_response_header[0]??'HTTP/1.1 500',9,3);return ['status'=>$status,'body'=>$raw===false?null:json_decode($raw,true)];}
