$first=ts_call('POST','/api/bridge/ingest',$packet,true);ts_check($first['status']===201&&!empty($first['body']['command']['id'])&&$first['body']['command']['command_type']==='ACK'&&$first['body']['command']['type']==='acknowledgement','ingest returns its queued ACK object');
$sessionB=$start('Session B '.$seq);$q=$pdo->prepare('SELECT ended_at FROM test_sessions WHERE id=?');$q->execute([(int)$sessionA['id']]);$closedAt=$q->fetchColumn();ts_check($closedAt!==false&&$closedAt!==null,'starting a session closes the previous active session');$second=ts_call('POST','/api/bridge/ingest',$packet,true);ts_check($second['status']===201&&empty($second['body']['duplicate'])&&!empty($second['body']['command']['id']),'same sequence is accepted and queued in a new session');
