$benchSession=$start('BENCH phase '.$seq,'BENCH');$benchActive=ts_call('GET','/api/test-sessions/active');ts_check(($benchActive['body']['active_session']['phase']??null)==='BENCH','BENCH session phase saves and is returned by active-session endpoint');$benchSeq=random_int(0,65535);$benchPacket=$packet;$benchPacket['uplink']['sequence_number']=$benchSeq;$benchIngest=ts_call('POST','/api/bridge/ingest',$benchPacket,true);ts_check($benchIngest['status']===201,'uplink is accepted in BENCH session');$benchLog=ts_call('GET','/api/logs/packets?node_id=H1&limit=200');$benchLogRow=array_values(array_filter($benchLog['body']['packets']??[],fn($row)=>(int)$row['sequence_number']===$benchSeq))[0]??null;ts_check(($benchLogRow['session_phase']??null)==='BENCH','packet log exposes the BENCH session phase');$csv=@file_get_contents($base.'/api/export.csv?type=packets',false,$csvContext);$csvLines=is_string($csv)?preg_split('/\r?\n/',$csv):[];$csvHeader2=$csvLines?str_getcsv(array_shift($csvLines)):[];$csvIndexes2=array_flip($csvHeader2);$benchCsv=false;foreach($csvLines as $line){$cells=str_getcsv($line);if((string)($cells[$csvIndexes2['sequence_number']??-1]??'')===(string)$benchSeq&&($cells[$csvIndexes2['session_phase']??-1]??'')==='BENCH')$benchCsv=true;}ts_check($benchCsv,'packet CSV exposes the BENCH session phase');
